/**
 * Typed API client for Bug Reports generated by the Testing Agent.
 */

import { apiGet, apiPatch } from './client';

export type BugSeverity = 'critical' | 'high' | 'medium' | 'low';
export type BugStatus = 'open' | 'fixed' | 'wont_fix' | 'escalated';

export interface BugReport {
  id: string;
  project_id: string;
  run_id: string;
  bug_id: string;
  req_id?: string | null;
  tc_id?: string | null;
  file_path?: string | null;
  function_name?: string | null;
  severity: BugSeverity;
  expected_result: string;
  actual_result: string;
  probable_cause?: string | null;
  iteration: number;
  status: BugStatus;
  fix_description?: string | null;
  created_at: string;
  updated_at: string;
}

export interface BugListResponse {
  bugs: BugReport[];
  total: number;
}

/**
 * List all bug reports for a project, optionally filtered by run_id or status.
 */
export async function listBugs(
  projectId: string,
  runId?: string,
  status?: string
): Promise<BugListResponse> {
  const params: Record<string, string | undefined> = {};
  if (runId) params.run_id = runId;
  if (status) params.status = status;
  return apiGet<BugListResponse>(`/projects/${encodeURIComponent(projectId)}/bugs`, params);
}

/**
 * Get details for a specific bug report.
 */
export async function getBugDetail(bugId: string): Promise<BugReport> {
  return apiGet<BugReport>(`/bugs/${encodeURIComponent(bugId)}`);
}

/**
 * Update status and optional fix description for a bug report.
 */
export async function updateBugStatus(
  bugId: string,
  status: BugStatus,
  fixDescription?: string
): Promise<BugReport> {
  return apiPatch<BugReport>(`/bugs/${encodeURIComponent(bugId)}`, {
    status,
    fix_description: fixDescription,
  });
}
